    /// <summary>
    /// Returns information about an emoji reaction. Returns a 404 error if the reaction is not found
    /// </summary>
    public Task<TdLib.TdApi.Objects.EmojiReaction> GetEmojiReactionAsync(string emoji = default)
    {

           using var activity =  StartCallActivity("GetEmojiReactionAsync", typeof(GetEmojiReaction).FullName ?? "GetEmojiReactionAsync");

           try
           {
             return client.GetEmojiReactionAsync(emoji);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
